import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { RouterProvider } from 'react-router-dom'
import { registerSW } from 'virtual:pwa-register'
import './index.css'
import { router } from './router'
import { DatabaseProvider, useDatabase } from '@/hooks/useDatabase'
import { DatabaseErrorScreen, SplashScreen } from '@/components/layout/BootScreens'

// Registers the offline service worker (generated by vite-plugin-pwa).
registerSW({ immediate: true })

function AppShell() {
  const { status, error, retry } = useDatabase()

  if (status === 'initializing') {
    return <SplashScreen />
  }

  if (status === 'error') {
    return <DatabaseErrorScreen error={error} onRetry={retry} />
  }

  return <RouterProvider router={router} />
}

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <DatabaseProvider>
      <AppShell />
    </DatabaseProvider>
  </StrictMode>,
)
